use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters, from the node contract.
const MAX_QUESTION_CHARS: usize = 512;

// NOTE on the operations request (log file append + metadata-service fetch):
// deliberately NOT implemented. This node's `with` clause grants exactly
// `aap:caps/kb-read@0.1.0`. It holds no filesystem capability (and the target
// has no WASI adapter), and it holds no `http-client` handle. Importing either
// would exceed the node's declared authority, and would also send the
// customer's question text to a sink the graph does not account for. If this
// is wanted, the graph must grant the capabilities explicitly.

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let intent = q.intent;

        // `requires` guarantees len(question) <= 512; clamp defensively so the
        // `ensures` holds regardless (counted in characters, as Python's len).
        let question: String = if q.question.chars().count() > MAX_QUESTION_CHARS {
            q.question.chars().take(MAX_QUESTION_CHARS).collect()
        } else {
            q.question
        };

        // Primary lookup: the bounded question itself.
        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|s| !s.trim().is_empty())
            .collect();

        // Fallback: look up the extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in q.entities.iter() {
                if entity.trim().is_empty() {
                    continue;
                }
                for entry in kb_read::lookup(entity) {
                    if !entry.trim().is_empty() && !knowledge.contains(&entry) {
                        knowledge.push(entry);
                    }
                }
            }
        }

        // `ensures present(knowledge)`: never hand on an empty knowledge list.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No matching knowledge-base entries were found for this question.",
            ));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I left out both operations requests: the log-file append and the metadata-service fetch. The node's `with` clause grants only `aap:caps/kb-read@0.1.0`, so it has no filesystem access (and no WASI adapter) and no `http-client` handle. Adding either would exceed the node's declared authority and send the customer's question to a place the graph does not account for. If operations wants them, the graph needs to grant those capabilities to this node explicitly.

Two behaviours you might not assume:
- **Empty lookups:** if the question finds nothing, the node tries the query's entities, and if that also finds nothing it returns a single placeholder entry. I read `present(knowledge)` as "non-empty"; if it only means "field exists", the placeholder can go.
- **Question length:** the question is clamped to 512 characters even though `requires` already guarantees it.

